(3166395, 443914, 53316, '<td valign="top">Hahahaha!!!! Awesome take on the challenge!!!</td>', 'Hahahaha!!!! Awesome take on the challenge!!!', '2007-01-01 03:40:17.000000', NULL, 1),
(3166398, 445005, 53316, '<td valign="top">Would have been better with a less yellow tone, I think. I do love the effect you have with the lights - very cool to look at.</td>', 'Would have been better with a less yellow tone, I think. I do love the effect you have with the lights - very cool to look at.', '2007-01-01 03:41:06.000000', NULL, 1),
(3166401, 444281, 53316, '<td valign="top">Border is maybe a little distracting but it does help a TON to show the "French" aspect of the title.</td>', 'Border is maybe a little distracting but it does help a TON to show the "French" aspect of the title.', '2007-01-01 03:43:36.000000', NULL, 1),
