(3168422, 443914, 50695, '<td valign="top">A Fan Killed at a David Cassidy Concert<br/> <br/> <br/>The mountain of your eyes,<br/>impassably beautiful,<br/>cannot distinguish me.<br/> <br/>I cannot imagine<br/>you could ever accept<br/>my kisses.<br/> <br/>In this way<br/>you are like dying,<br/>a crossing improvised<br/> <br/>in desperation,<br/>and only in darkness<br/>can I meet your gaze.<br/> <br/> <br/>Donald Zirilli<br/>12/27/99</td>', 'A Fan Killed at a David Cassidy Concert  The mountain of your eyes,impassably beautiful,cannot distinguish me. I cannot imagineyou could ever acceptmy kisses. In this wayyou are like dying,a crossing improvised in desperation,and only in darknesscan I meet your gaze.  Donald Zirilli12/27/99', '2007-01-01 21:44:13.000000', NULL, 1),
(3168428, 443072, 46330, '<td valign="top">Nice composition, but the post processing looks too overdone.</td>', 'Nice composition, but the post processing looks too overdone.', '2007-01-01 21:46:16.000000', NULL, 1),
(3168429, 445005, 51802, '<td valign="top">Nice bokeh effect.  The strand of lights hanging down from the bottom of the tree is a bit distracting though.</td>', 'Nice bokeh effect.  The strand of lights hanging down from the bottom of the tree is a bit distracting though.', '2007-01-01 21:49:07.000000', NULL, 1),
(3168430, 444395, 46330, '<td valign="top">Nice ornament, but the lighting is too harsh and a perch that wasn''t quite so busy with all of those branches sticking in every direction would also have helped improve the composition.</td>', 'Nice ornament, but the lighting is too harsh and a perch that wasn''t quite so busy with all of those branches sticking in every direction would also have helped improve the composition.', '2007-01-01 21:49:54.000000', NULL, 1),
(3168431, 443745, 46330, '<td valign="top">Nice composition and an original take on the challenge.</td>', 'Nice composition and an original take on the challenge.', '2007-01-01 21:51:12.000000', NULL, 1),
(3168438, 445339, 51802, '<td valign="top">The DoF is a little too shallow in this shot.  It might also help if the light were stronger in order to bring out the brightness of the rings.</td>', 'The DoF is a little too shallow in this shot.  It might also help if the light were stronger in order to bring out the brightness of the rings.', '2007-01-01 21:53:08.000000', NULL, 1),
(3168455, 445235, 51802, '<td valign="top">Wonderful shot.  I really like the arrangement of the rings.  Only minor complaint is that the greenery in the background seems harshly cropped.</td>', 'Wonderful shot.  I really like the arrangement of the rings.  Only minor complaint is that the greenery in the background seems harshly cropped.', '2007-01-01 22:03:26.000000', NULL, 1),
(3168459, 444009, 51802, '<td valign="top">Very unique!  I like the different angles of the rings.  The contrast of light and dark is wonderful.</td>', 'Very unique!  I like the different angles of the rings.  The contrast of light and dark is wonderful.', '2007-01-01 22:06:47.000000', NULL, 1),
(3168482, 444029, 63503, '<td valign="top">Where the heck did you find the right number of swans at the precise time ??!! great picture</td>', 'Where the heck did you find the right number of swans at the precise time ??!! great picture', '2007-01-01 22:24:26.000000', NULL, 1),
(3168486, 445191, 63503, '<td valign="top">Nice idea, perhaps 24 drumsticks would have been more accurate. I like the picture though</td>', 'Nice idea, perhaps 24 drumsticks would have been more accurate. I like the picture though', '2007-01-01 22:26:01.000000', NULL, 1),
(3168488, 444281, 63503, '<td valign="top">I understand your intention, I am not sure it came out the way you wanted it, very nice effort though, and the picture as a whole is pleasant to look at.</td>', 'I understand your intention, I am not sure it came out the way you wanted it, very nice effort though, and the picture as a whole is pleasant to look at.', '2007-01-01 22:27:52.000000', NULL, 1),
